UNITS = []

UNITS.append(dict(id="N4", part="National", title="Valuation, Appraisal & Investment Analysis",
 objectives=["Distinguish price, cost and value","Apply the three approaches to value","Recognize appraisal principles and regulations","Do basic income-property analysis"],
 lessons=[
 dict(title="Value concepts and principles",
  body=["**Value** is the present worth of future benefits. **Market value** is the most probable price a property should bring in a competitive, open market with a willing, informed buyer and seller, neither under duress, reasonable exposure time, and payment in cash or equivalent. **Price** is what was actually paid. **Cost** is the expense of production. **Assessed value** is for taxes; **insurable value** excludes land.",
  "Four elements of value (**DUST**): **D**emand, **U**tility, **S**carcity, **T**ransferability. Value principles: **highest and best use** (legally permissible, physically possible, financially feasible, maximally productive), **substitution** (a buyer won't pay more than the cost of an equal substitute), **supply and demand**, **conformity**, **progression** (a lesser property gains value near better ones), **regression** (a better property loses value near lesser ones), **contribution**, **anticipation**, **change**, **balance**, **competition**.",
  "**Depreciation** is loss in value from any cause. **Physical deterioration** (curable or incurable), **functional obsolescence** (design defects such as outdated floor plan; curable/incurable), **external (economic) obsolescence** (outside the property, e.g., nearby landfill; **always incurable**). **Curable** means the cost to cure is less than the value added."],
  key=["DUST: Demand, Utility, Scarcity, Transferability","External obsolescence is always incurable","Highest and best use: legal, possible, feasible, most productive"],
  example="A beautiful house next to a new rendering plant loses value for a reason outside the lot — external obsolescence — and the owner cannot cure it."),
 dict(title="The three approaches to value",
  body=["**1. Sales comparison (market data) approach** — best for single-family homes and vacant land. Select **comparables** (recent, nearby, similar sales), then **adjust the comparable to match the subject**: if the comp is *better*, **subtract**; if the comp is *worse*, **add**. Never adjust the subject. Adjust for time, location, physical features, terms of sale. Adjust the price of the comp, not the subject's.",
  "**2. Cost approach** — best for new, special-purpose or unique buildings (schools, churches). **Value = reproduction or replacement cost of improvements − accumulated depreciation + land value**. **Reproduction cost** replicates the exact building; **replacement cost** uses modern equivalents. Land is valued by sales comparison. Methods: square-foot, unit-in-place, quantity survey.",
  "**3. Income approach** — best for investment property. **Value = Net Operating Income ÷ Capitalization Rate**.",
  "- Potential gross income (PGI) − vacancy and collection loss = Effective gross income (EGI)",
  "- EGI − operating expenses = **NOI**. Operating expenses include taxes, insurance, maintenance, management, utilities, reserves. **Not** included: mortgage payments (debt service), income taxes, depreciation, capital improvements.",
  "- **Gross rent multiplier (GRM)** = price ÷ monthly gross rent (for small residential rentals); **gross income multiplier (GIM)** uses annual income.",
  "**Reconciliation** weighs the approaches to reach a final opinion; the appraiser gives the most weight to the approach with the best data for that property type. **CMA vs appraisal**: a broker price opinion/CMA is not an appraisal; only licensed/certified appraisers may do appraisals for federally related transactions. Appraiser independence rules (post-2008 **Dodd-Frank**/AMCs) prohibit pressure on appraisers; agents must not influence value."],
  key=["Comp better than subject → subtract; comp worse → add","Value = NOI ÷ cap rate","Cost approach: replacement cost − depreciation + land"],
  example="Subject has no garage. A comp with a garage worth $12,000 sold for $250,000. Adjusted comp = $238,000."),
 dict(title="Investment basics and appraisal regulation",
  body=["Key investment measures: **cash flow** (NOI − debt service), **cap rate** = NOI ÷ value, **ROI** = annual return ÷ investment, **cash-on-cash return** = annual pre-tax cash flow ÷ cash invested, **loan-to-value (LTV)**, **debt service coverage ratio (DSCR)** = NOI ÷ annual debt service (lenders usually want ≥ 1.2).",
  "**Leverage** is using borrowed money to magnify returns (and losses). **Appreciation** is value increase; **depreciation (tax)** is a non-cash expense that shelters income for investors (residential 27.5 years, commercial 39 years straight line). **1031 exchange** defers capital gain when like-kind investment real property is swapped within strict timelines (45 days to identify, 180 days to close).",
  "**Appraisal regulation**: Title XI of FIRREA requires appraisers to be state-licensed or certified for federally related transactions; USPAP sets standards; the Appraisal Subcommittee oversees. In Mississippi, appraisers are licensed and certified by a separate state appraiser board, not by licensing as a real estate salesperson or broker; confirm the current agency with the state.",
  "**Home inspection** and **appraisal** have different purposes: an inspection evaluates condition; an appraisal estimates value for the lender."],
  key=["DSCR = NOI ÷ debt service","1031: identify 45 days, close 180 days","Appraisers are regulated separately from real estate licensees"],
  example="NOI $60,000; debt service $48,000 → DSCR 1.25, acceptable to most lenders."),
 ],
 quiz=[
 ("Value = NOI ÷ cap rate is the:", "income approach", ["cost approach","sales comparison approach","GRM approach"], "Direct capitalization."),
 ("If a comparable is superior to the subject, the appraiser should:", "subtract the feature's value from the comparable's price", ["add to the comparable","adjust the subject","ignore it"], "Make the comp like the subject."),
 ("Which depreciation is always incurable?", "external obsolescence", ["physical deterioration","functional obsolescence","deferred maintenance"], "Outside the property."),
 ("The best approach for a new church is the:", "cost approach", ["income approach","sales comparison approach","GRM"], "Few comps for special-purpose."),
 ("Which is NOT deducted when computing NOI?", "mortgage payments", ["property taxes","insurance","management fees"], "Debt service is below NOI."),
 ("DUST stands for demand, utility, scarcity and:", "transferability", ["taxation","tenure","time"], "Elements of value."),
 ("The principle that a buyer won't pay more than the cost of an equally desirable substitute is:", "substitution", ["conformity","progression","contribution"], "Foundation of the sales comparison approach."),
 ("A lesser property gains value from nearby better properties. This is:", "progression", ["regression","conformity","anticipation"], "Progression."),
 ("Market value assumes:", "a willing, informed buyer and seller, neither under duress", ["a quick forced sale","related parties","only cash sales"], "Standard definition."),
 ("Highest and best use must be legally permissible, physically possible, financially feasible and:", "maximally productive", ["publicly approved","newly built","commercial"], "Four tests."),
 ("GRM is:", "price ÷ monthly gross rent", ["NOI ÷ price","annual rent ÷ expenses","price ÷ NOI"], "GRM."),
 ("Depreciation for tax on residential rental property is generally:", "27.5 years", ["15 years","39 years","50 years"], "Commercial is 39."),
 ("A 1031 exchange requires identifying replacement property within:", "45 days", ["30 days","90 days","180 days"], "Close within 180."),
 ("A CMA prepared by a real estate agent:", "is not an appraisal", ["can replace an appraisal for a federal loan","requires USPAP certification","is binding on the lender"], "Agents give opinions, not appraisals."),
 ]))

UNITS.append(dict(id="N5", part="National", title="Real Estate Finance",
 objectives=["Explain mortgage instruments, lien theory and deeds of trust","Compare loan programs (conventional, FHA, VA, USDA)","Apply RESPA/TILA/TRID, ECOA and lending rules","Understand the primary and secondary markets"],
 lessons=[
 dict(title="Financing instruments and mortgage basics",
  body=["Two documents: the **promissory note** (the debt; the borrower's promise to pay) and the **security instrument** (mortgage or **deed of trust**) which pledges the property. The note is the evidence of debt; the security instrument creates the lien.",
  "**Mortgage** (two parties: **mortgagor**=borrower, **mortgagee**=lender) is usually foreclosed judicially in most lien-theory states. **Deed of trust** (three parties: **trustor**=borrower, **beneficiary**=lender, **trustee**=neutral third party holding title for the lender) usually allows **non-judicial foreclosure** under a **power of sale**. Mississippi commonly uses deeds of trust with power of sale.",
  "Key clauses: **acceleration** (entire balance due on default), **due-on-sale** (alienation) clause, **defeasance** (mortgage void on payoff), **prepayment penalty**, **escrow** (impounds for taxes and insurance), **subordination** (changing lien priority).",
  "**Payment types**: **amortized** (principal + interest, fully pays off), **interest-only**, **balloon**, **adjustable-rate (ARM)** with index + margin, caps and adjustment periods, **graduated payment**, **reverse mortgage** (HECM, FHA-insured, borrower 62+, loan due when the borrower leaves/dies).",
  "**Interest** accrues on the unpaid balance; in the early years of a fixed loan, most of the payment is interest. **Points**: one discount point = 1% of the loan, paid to lower the interest rate (a point buys about 1/8% reduction, varying). **Origination fee** pays the lender's processing. **PMI** (private mortgage insurance) is typically required when LTV exceeds 80% on a conventional loan and can be canceled at 80% (automatic termination at 78% under the Homeowners Protection Act).",
  "**Assumption** (buyer takes over the existing loan; seller stays secondarily liable unless released by novation), **'subject to'** (buyer takes title with the loan outstanding; seller remains liable), **wraparound** and **land contract (contract for deed / installment contract)** where the seller keeps legal title until payment — equitable title passes to the buyer immediately."],
  key=["Note = debt; mortgage/deed of trust = lien","Deed of trust has three parties and allows power of sale","PMI is generally required above 80% LTV on conventional loans"],
  example="A $200,000 loan at 3 points: points cost $6,000 (3% × $200,000)."),
 dict(title="Loan programs and underwriting",
  body=["**Conventional loans** are not government-insured. **Conforming** loans meet Fannie Mae/Freddie Mac limits (set annually by FHFA); **jumbo** loans exceed them. Typical minimum down payment 3–5%; PMI if under 20%.",
  "**FHA** (Dept. of Housing and Urban Development): insures lender; minimum down payment 3.5% with 580+ credit score (10% for 500–579); requires an **upfront MIP** and **annual MIP**; property standards; assumable (subject to rules).",
  "**VA**: guaranteed (not insured) by the Dept. of Veterans Affairs for eligible veterans, service members, and some surviving spouses; **no down payment** generally required and no monthly PMI; a **funding fee** applies (waived for some); **Certificate of Eligibility (COE)**; the VA Notice of Value (NOV) sets value.",
  "**USDA Rural Development (Section 502)**: for eligible rural areas and income limits; 100% financing possible.",
  "**Underwriting** evaluates the **4 Cs**: credit, capacity, collateral, capital. Ratios: **front-end (housing) ratio** = PITI ÷ gross monthly income; **back-end (total debt) ratio** = (PITI + other debts) ÷ gross monthly income. Typical conventional guidelines: ~28/36 historically; modern automated underwriting allows higher (FHA up to ~31/43 or more with compensating factors). **PITI** = principal, interest, taxes, insurance. **LTV** = loan ÷ lesser of price or appraised value.",
  "**Qualified Mortgage (QM)** rules under the **Ability-to-Repay** rule limit risky features and generally cap points and fees.",
  "**Seller concessions**, **buydowns**, and **seller financing** (purchase-money mortgage) are negotiated in the contract; lenders cap concessions."],
  key=["FHA: 3.5% down at 580+; VA: no down payment, guaranteed; USDA: rural","Front-end ratio = PITI ÷ gross income; back-end adds all other debts","LTV uses the lesser of price or appraised value"],
  example="Price $250,000, appraisal $240,000, loan $228,000 → LTV = 228,000 ÷ 240,000 = 95%."),
 dict(title="Federal lending laws and the mortgage markets",
  body=["- **TILA / Regulation Z** — disclosure of credit terms (APR, finance charge, amount financed, total payments). **Advertising triggers**: stating a *triggering term* (down payment amount, payment amount, number of payments, finance charge or **interest rate in monetary terms**) requires full disclosure of the loan's APR, terms and repayment schedule. A statement like 'Easy terms' or 'Low down payment' is non-triggering; 'Only $1,000 down' is triggering.",
  "- **RESPA / Regulation X** — applies to federally related loans on 1–4 family residential; requires settlement-cost disclosures; **prohibits kickbacks and referral fees** (Section 8) and limits escrow cushions (generally two months). Affiliated business arrangements require disclosure.",
  "- **TRID (TILA-RESPA Integrated Disclosure)** — the **Loan Estimate** within **3 business days** of application and the **Closing Disclosure** at least **3 business days** before consummation. A **3-business-day right of rescission** applies to refinancing of a primary residence and home-equity loans (not purchase loans).",
  "- **ECOA** — prohibits credit discrimination on race, color, religion, national origin, sex, marital status, age (if of legal capacity), receipt of public assistance, or exercise of consumer-credit rights; **adverse-action notice** within 30 days.",
  "- **Fair Credit Reporting Act**, **Homeowners Protection Act** (PMI cancellation), **Equal Credit**, **HMDA** (mortgage data to monitor lending patterns), **redlining** is illegal.",
  "**Primary market** — originators (banks, credit unions, mortgage bankers/brokers) lend to borrowers. **Secondary market** — Fannie Mae, Freddie Mac (GSEs), **Ginnie Mae** (government-owned; guarantees securities backed by FHA/VA/USDA loans) buy/pool loans into **mortgage-backed securities** to supply liquidity. **Federal Reserve** controls monetary policy (discount rate, reserve requirements, open-market operations).",
  "**Mortgage loan originator** licensing falls under the **SAFE Act/NMLS**; real estate licensees can't originate loans without proper licensing, and can't steer."],
  key=["Loan Estimate: 3 business days after application; Closing Disclosure: 3 business days before closing","RESPA bans kickbacks for settlement-service referrals","Ginnie Mae guarantees securities backed by FHA/VA loans"],
  example="Ad says 'Only 3% down, $1,200/month.' Both are triggering terms; the ad must include APR, term and repayment details."),
 ],
 quiz=[
 ("The promissory note is:", "evidence of the debt", ["the lien itself","the deed","a covenant"], "The security instrument creates the lien."),
 ("In a deed of trust, the neutral third party is the:", "trustee", ["trustor","beneficiary","mortgagee"], "Trustee holds title for security."),
 ("The clause that makes the entire balance due on default is:", "acceleration", ["defeasance","subordination","alienation"], "Acceleration."),
 ("One discount point on a $300,000 loan costs:", "$3,000", ["$300","$30,000","$1,500"], "1% × 300,000."),
 ("PMI on a conventional loan is generally required when LTV exceeds:", "80%", ["70%","90%","95%"], "Under 20% down."),
 ("VA loans are:", "guaranteed by the VA", ["insured by the VA","insured by FHA","made by Fannie Mae"], "VA guarantees; FHA insures."),
 ("Minimum FHA down payment with a 580+ credit score:", "3.5%", ["0%","5%","10%"], "3.5%."),
 ("LTV on a $250,000 sale with $240,000 appraisal and $228,000 loan is:", "95%", ["91.2%","92%","100%"], "228/240."),
 ("Back-end ratio includes:", "PITI plus all other monthly debts", ["only PITI","only taxes","only car payments"], "Total debt ratio."),
 ("An ad saying 'Only $2,000 down!' triggers:", "full TILA disclosures", ["no disclosure","only RESPA disclosure","only state law"], "Down payment is a triggering term."),
 ("The Loan Estimate must be delivered within:", "3 business days of application", ["1 day","10 days","at closing"], "TRID."),
 ("The Closing Disclosure must be received at least:", "3 business days before closing", ["24 hours before","at closing","7 days before"], "TRID."),
 ("RESPA Section 8 prohibits:", "kickbacks for referrals of settlement services", ["points","escrow accounts","appraisals"], "No referral fees."),
 ("Ginnie Mae:", "guarantees securities backed by FHA/VA/USDA loans", ["is a private lender","sets the discount rate","insures conventional loans"], "Government-owned."),
 ("ECOA prohibits credit discrimination based on:", "marital status", ["credit history","income","debts"], "Protected bases."),
 ("In a land contract, legal title passes:", "when the contract is fully paid", ["at signing","at inspection","at the first payment"], "Equitable title passes first."),
 ]))

UNITS.append(dict(id="N6", part="National", title="Contracts",
 objectives=["List the elements of a valid contract","Classify contracts by status and enforceability","Apply the statute of frauds and key contract provisions","Explain default, remedies and discharge"],
 lessons=[
 dict(title="Elements and classification",
  body=["A valid contract has **(1) competent parties, (2) mutual consent (offer and acceptance, 'meeting of the minds'), (3) lawful object, (4) consideration, and (5) in writing when required (statute of frauds)**. Memory aid: **COLA**, with a writing for real estate: Competent parties, Offer and acceptance, Legal purpose, Adequate consideration (plus writing).",
  "**Competency**: minors, persons declared mentally incompetent, and persons intoxicated may lack capacity; contracts by minors are generally **voidable** at the minor's option.",
  "**Consent defects**: fraud, misrepresentation, mistake, duress, undue influence make a contract **voidable**.",
  "**Classification**:",
  "- **Express** (stated) vs **implied** (by conduct)",
  "- **Bilateral** (promise for promise—most real estate contracts) vs **unilateral** (promise for an act—an open listing or option)",
  "- **Executory** (not fully performed) vs **executed** (fully performed)",
  "- **Valid**, **void** (no legal effect), **voidable** (one party may cancel), **unenforceable** (valid but cannot be enforced in court, e.g., oral contract for land)",
  "**Offer**: terminated by acceptance, rejection, **counteroffer** (a counteroffer rejects the original), revocation before acceptance, lapse of time, death or incapacity. An **acceptance** must mirror the offer and be communicated.",
  "**Consideration**: something of value (money, promise, act). Love and affection ('good consideration') supports a deed but not typically a contract. **Statute of frauds** — contracts to sell, convey or lease real property for more than one year must be in writing and signed by the party to be charged. Mississippi follows the statute of frauds. An agent's authority to sell must also be in writing."],
  key=["Real estate contracts for sale must be written and signed","Counteroffer = rejection of the original offer","Voidable vs void vs unenforceable"],
  example="Seller says yes to the price but changes the closing date in writing. That is a counteroffer; the buyer's original offer is dead and can't be accepted later."),
 dict(title="Purchase contract provisions and contingencies",
  body=["A **purchase and sale agreement** typically includes: parties, legal description, price, **earnest money**, financing terms, contingencies, closing date, possession, prorations, title evidence, personal property included, default remedies, and disclosures.",
  "**Earnest money** is a good-faith deposit; it is not required for validity but shows the buyer's seriousness. It is held in the broker's **trust (escrow) account**; the broker may never commingle it or use it. If the parties dispute it, the broker typically holds the funds until a written release, or interpleader/court order.",
  "**Contingencies** make performance depend on an event: financing, appraisal, inspection, sale of buyer's current home, title. Each should have a **deadline** and a defined remedy (cancel, renegotiate, waive). **Time is of the essence** makes deadlines strict.",
  "**Equitable title** — buyer's interest between contract and closing. **Doctrine of equitable conversion**. **Risk of loss** before closing is allocated by contract; the Uniform Vendor and Purchaser Risk Act places it on the seller until title or possession passes (state-specific).",
  "**Option** — buyer pays for the right (not the obligation) to buy within a time; unilateral; the optionor must honor it; the optionee can walk away and lose the option fee. **Right of first refusal** gives a person the first chance to match an offer. **Assignment** transfers contract rights; **novation** substitutes a new party and releases the original.",
  "**Lease-purchase** (lease-option) combines lease and option.",
  "**Default and remedies**: if the buyer defaults — seller may keep earnest money (if liquidated damages), sue for damages, or sue for **specific performance** (court orders the sale; real property is unique). If the seller defaults — buyer may sue for specific performance, damages, or rescission and return of deposit. **Rescission** returns parties to their original positions. **Liquidated damages** pre-agree on damages. **Contract discharge**: full performance, mutual agreement, impossibility, operation of law, breach, statute of limitations."],
  key=["Specific performance is the buyer's usual remedy against a seller","Liquidated damages: pre-agreed amount, often the earnest money","Options are unilateral contracts"],
  example="A buyer's financing contingency expires Friday. If the buyer neither waives nor cancels in writing by then, the contract may proceed with the contingency lost, depending on the contract's terms."),
 ],
 quiz=[
 ("Which is NOT an essential element of a valid contract?", "earnest money", ["competent parties","consideration","legal purpose"], "Earnest money is common but not required."),
 ("A contract that is valid but cannot be enforced in court is:", "unenforceable", ["void","voidable","executed"], "e.g., oral land contract."),
 ("A contract signed by a minor is generally:", "voidable", ["void","executed","unilateral"], "Minor may disaffirm."),
 ("A counteroffer:", "terminates the original offer", ["keeps the original offer open","is acceptance","is a lease"], "It is a rejection."),
 ("An option contract is:", "unilateral", ["bilateral","implied","void"], "Only optionor is bound."),
 ("A bilateral contract involves:", "a promise exchanged for a promise", ["a promise for an act","no consideration","an oral agreement only"], "Most sales contracts."),
 ("The statute of frauds requires which contracts to be in writing?", "real estate sales contracts", ["all verbal promises","every lease of any length","only mortgages"], "Sale of land."),
 ("A buyer's remedy to force the seller to convey is:", "specific performance", ["liquidated damages","novation","rescission only"], "Land is unique."),
 ("'Time is of the essence' means:", "deadlines must be strictly met", ["extensions are automatic","performance is optional","the contract is void"], "Strict deadlines."),
 ("A substitution of a new party that releases the original is:", "novation", ["assignment","rescission","defeasance"], "Novation."),
 ("Earnest money in a broker's possession must be:", "held in a trust or escrow account", ["deposited to the broker's operating account","kept in cash","given to the seller"], "Never commingled."),
 ("Fraud makes a contract:", "voidable", ["void","executed","bilateral"], "Defrauded party may rescind."),
 ("Equitable title is held by the:", "buyer after signing the contract", ["seller","broker","lender at all times"], "Between contract and closing."),
 ("Rescission:", "returns the parties to their pre-contract positions", ["enforces the contract","creates a lease","transfers title"], "Cancels."),
 ]))
